<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to rewrite:
<original_code>
#include <iostream>
#include<bits/stdc++.h>
#include<math.h>

using namespace std;


#define fast ios_base::sync_with_stdio(false);cin.tie(NULL);cout.tie(NULL);
#define pb push_back
#define pf push_front
#define mp make_pair
#define mt make_tuple
#define popb pop_back
#define popf pop_front
#define int long long int
#define PI 3.1415926535897932
#define all(v) v.begin(),v.end()
#define endl "\n"
#define rep(i,a,b)  for(int i=a;i<b;i++)
#define prec(x)  cout<<fixed<<setprecision(x)
#define toup(su) transform(su.begin(), su.end(), su.begin(), ::toupper); 
#define tolow(su) transform(su.begin(), su.end(), su.begin(), ::tolower); 
int M=1000000007;

int gcd(int a, int b)
{
  return (b==0)?a:gcd(b,a%b);
}




signed main()
{
    fast


 #ifndef ONLINE_JUDGE
    freopen("input.txt", "r", stdin);
    freopen("output.txt", "w", stdout);
    #endif


   int t=1;
   //cin>>t;

   while(t--)
   {
    double x,y,n; cin>>x>>y>>n;
    int a,b;
    double req=(x/y);
    double now, diff;
    double mn=1e9;
    int num;
    if(y<=n)
    {
        a=x; b=y;
    }

    else
    {
        for(int i=n;i>=1;i--)
        {
            int deno =i;
            double z=(double(deno)*req);

            if(z-floor(z)<=0.5) num=floor(z);

            else 
                num=floor(z)+1;

            now=double(num)/deno;

            diff= abs(now-req);



            if(diff<=mn)
            {
                mn=diff; a=num; b=deno;
            }

        }
    }
    int g=gcd(a,b);
    a=a/g;
    b=b/g;

    cout<<a<<"/"<<b<<endl;

}

    return 0;   

  }    


